def transform_rect(grid, debug=False):
    from collections import Counter
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find 4-connected component sizes and all cells in singletons.
    seen=set(); single=[]; totals=Counter()
    for r in range(h):
      for c in range(w):
        v=grid[r][c]; totals[v]+=1
        if (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c))
        for x,y in q:
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==v:
              seen.add((nx,ny)); q.append((nx,ny))
        if len(q)==1: single.append((r,c))
    structural=[v for v,n in totals.items() if v!=bg and n>=4]
    # Summed-area tables for each structural color.
    pref={}
    for v in structural:
      p=[[0]*(w+1) for _ in range(h+1)]
      for r in range(h):
        s=0
        for c in range(w):
          s += grid[r][c]==v
          p[r+1][c+1]=p[r][c+1]+s
      pref[v]=p
    changes=[]
    for r,c in single:
      best=None
      for v in structural:
        p=pref[v]
        for r1 in range(r+1):
          for r2 in range(r,h):
            hh=r2-r1+1
            if hh<2: continue
            for c1 in range(c+1):
              for c2 in range(c,w):
                ww=c2-c1+1
                if ww<2: continue
                area=hh*ww
                n=p[r2+1][c2+1]-p[r1][c2+1]-p[r2+1][c1]+p[r1][c1]
                err=area-n
                if err<=0 or err>=min(hh,ww): continue
                if n*100 < area*85: continue
                # prefer high density, then more supporting cells, then smaller box
                score=(n/area,n, -area)
                if best is None or score>best[0]: best=(score,v,(r1,c1,r2,c2,err,n,area))
      if best:
        out[r][c]=best[1]; changes.append((r,c,grid[r][c],best[1],best[2]))
      else:
        out[r][c]=bg
    if debug:return out,changes,bg,structural
    return out
